import React, { useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';

const CompleteUploadPageFixed = () => {
  const navigate = useNavigate();
  const [files, setFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef(null);

  const handleFileUpload = (e) => {
    const uploadedFiles = Array.from(e.target.files);
    setFiles(uploadedFiles);
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragOver(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setDragOver(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragOver(false);
    const droppedFiles = Array.from(e.dataTransfer.files);
    setFiles(droppedFiles);
  };

  const handleGenerateData = () => {
    setUploading(true);
    setTimeout(() => {
      const mockCompanyData = {
        company: "Tech Innovations Pvt Ltd",
        revenue: "15.5",
        industry: "Technology",
        financial_metrics: {
          monthly_revenue: "12.8",
          monthly_profit: "2.1",
          cash_flow: "3.2",
          total_liabilities: "45.2",
          equity: "125.3"
        }
      };

      localStorage.setItem('companyData', JSON.stringify({
        is_multi_company: false,
        companies: [mockCompanyData]
      }));

      setUploading(false);
    }, 2000);
  };

  return (
    <div style={{ 
      minHeight: '100vh', 
      background: 'linear-gradient(135deg, #1e40af 0%, #0f766e 50%, #0891b2 100%)',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      color: 'white'
    }}>
      <div style={{ textAlign: 'center', maxWidth: '800px' }}>
        <div style={{ fontSize: '48px', marginBottom: '24px' }}>🏦</div>
        <h1 style={{ fontSize: '32px', fontWeight: 'bold', marginBottom: '16px' }}>
          AI Credit Decisioning Engine
        </h1>
        <p style={{ fontSize: '18px', marginBottom: '32px', color: 'rgba(255,255,255,0.8)' }}>
          Upload your financial documents to get dynamic credit analysis
        </p>

        <div
          style={{
            background: dragOver 
              ? 'rgba(255, 255, 255, 0.2)' 
              : 'rgba(255, 255, 255, 0.1)',
            backdropFilter: 'blur(20px)',
            borderRadius: '20px',
            padding: '32px',
            border: dragOver 
              ? '2px solid rgba(255, 255, 255, 0.6)' 
              : '2px dashed rgba(255, 255, 255, 0.3)',
            textAlign: 'center',
            marginBottom: '32px',
            transition: 'all 0.3s ease'
          }}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          <input
            ref={fileInputRef}
            type="file"
            multiple
            onChange={handleFileUpload}
            style={{
              display: 'none'
            }}
          />
          <div style={{ fontSize: '48px', marginBottom: '16px' }}>📁</div>
          <p style={{ fontSize: '18px', marginBottom: '16px', color: 'white' }}>
            Drag & Drop files here or click to browse
          </p>
          <button
            onClick={() => fileInputRef.current?.click()}
            style={{
              padding: '12px 24px',
              background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
              color: 'white',
              borderRadius: '8px',
              cursor: 'pointer',
              fontSize: '14px',
              fontWeight: '600',
              transition: 'all 0.3s ease',
              border: 'none'
            }}
          >
            📤 Choose Files
          </button>
          <p style={{ fontSize: '14px', marginTop: '12px', color: 'rgba(255,255,255,0.7)' }}>
            Supports multiple files: PDF, Excel, Word, Images
          </p>
        </div>

        {files.length > 0 && (
          <div style={{ marginBottom: '24px' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
              <h3 style={{ fontSize: '18px', color: 'white', margin: 0 }}>
                Selected Files ({files.length})
              </h3>
              <button
                onClick={() => setFiles([])}
                style={{
                  background: '#ef4444',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '6px 12px',
                  cursor: 'pointer',
                  fontSize: '12px',
                  fontWeight: '600'
                }}
              >
                Clear All
              </button>
            </div>
            <div style={{ maxHeight: '200px', overflowY: 'auto' }}>
              {files.map((file, index) => (
                <div key={index} style={{
                  background: 'rgba(255, 255, 255, 0.1)',
                  padding: '12px',
                  borderRadius: '8px',
                  marginBottom: '8px',
                  display: 'flex',
                  justifyContent: 'space-between',
                  alignItems: 'center',
                  transition: 'all 0.3s ease'
                }}>
                  <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                    <div style={{ fontSize: '20px' }}>
                      {file.type.includes('pdf') ? '📄' : 
                       file.type.includes('excel') || file.name.endsWith('.xlsx') || file.name.endsWith('.xls') ? '📊' :
                       file.type.includes('word') || file.name.endsWith('.docx') || file.name.endsWith('.doc') ? '📝' :
                       file.type.includes('image') ? '🖼️' : '📎'}
                    </div>
                    <div>
                      <div style={{ fontSize: '14px', fontWeight: '600', color: 'white' }}>
                        {file.name}
                      </div>
                      <div style={{ fontSize: '12px', color: 'rgba(255,255,255,0.7)' }}>
                        {(file.size / 1024 / 1024).toFixed(2)} MB • {file.type || 'Unknown type'}
                      </div>
                    </div>
                  </div>
                  <button
                    onClick={() => setFiles(files.filter((_, i) => i !== index))}
                    style={{
                      background: '#ef4444',
                      color: 'white',
                      border: 'none',
                      borderRadius: '6px',
                      padding: '6px 12px',
                      cursor: 'pointer',
                      fontSize: '12px',
                      fontWeight: '600',
                      transition: 'all 0.3s ease'
                    }}
                  >
                    Remove
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        <button
          onClick={handleGenerateData}
          disabled={uploading || files.length === 0}
          style={{
            background: uploading 
              ? '#6b7280' 
              : 'linear-gradient(135deg, #10b981, #059669)',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            padding: '16px 32px',
            cursor: uploading ? 'not-allowed' : 'pointer',
            fontSize: '16px',
            fontWeight: '600',
            transition: 'all 0.3s ease',
            boxShadow: '0 4px 6px rgba(16, 185, 129, 0.2)',
            opacity: uploading ? 0.7 : 1
          }}
        >
          {uploading ? (
            <>
              <div style={{
                width: '20px',
                height: '20px',
                border: '2px solid white',
                borderTop: '2px solid transparent',
                borderRadius: '50%',
                animation: 'spin 1s linear infinite',
                marginRight: '12px',
                display: 'inline-block',
                verticalAlign: 'middle'
              }}></div>
              Processing...
            </>
          ) : (
            'Generate Dynamic Analysis'
          )}
        </button>

        {files.length > 0 && (
          <div style={{ display: 'flex', gap: '16px' }}>
            <button
              onClick={() => navigate('/dashboard')}
              style={{
                background: 'linear-gradient(135deg, #3b82f6, #2563eb)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(59, 130, 246, 0.2)',
                marginRight: '12px'
              }}
            >
              📊 View Static Dashboard
            </button>
            <button
              onClick={() => navigate('/dynamic-dashboard')}
              style={{
                background: 'linear-gradient(135deg, #10b981, #059669)',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                padding: '16px 32px',
                cursor: 'pointer',
                fontSize: '16px',
                fontWeight: '600',
                transition: 'all 0.3s ease',
                boxShadow: '0 4px 6px rgba(16, 185, 129, 0.2)',
                marginRight: '12px'
              }}
            >
              🚀 View Dynamic Dashboard
            </button>
            <button
              onClick={() => navigate('/research')}
              style={{
                background: 'linear-gradient(135deg, #8b5cf6, #7c3aed)',
                color: 'white',
                border: 'none',
